sys_script_client.script:
function onSubmit() {
    //Type appropriate comment here, and begin script below

 if(g_user.hasRole('x_1590789_bases.bases_administrator') && g_form.isNewRecord()) {
		var registrationSysId = g_form.getUniqueValue();
		var baseSysId = g_form.getValue('base');

		updateSpaces(baseSysId);

		return true;
     }

 }

 // Função para status
 function updateStatus(registrationSysId) {
     var ga = new GlideAjax('BasesUtilsAjax');
     ga.addParam('sysparm_name', 'updateStatus');
     ga.addParam('sysparm_registration_name', registrationSysId);
     ga.getXMLAnswer(function(response) {
         if (response === 'true') {
             return true;
         } else {
             return false;
         }
     });
 }

 // Função para atualizar as vagas
 function updateSpaces(baseSysId) {
     var ga = new GlideAjax('BasesUtilsAjax');
     ga.addParam('sysparm_name', 'updateSpaces');
     ga.addParam('sysparm_base_name', baseSysId);
     ga.getXMLAnswer(function(response) {
         if (response === 'true') {
             g_form.addInfoMessage("As vagas dessa Base foram atualizadas")
         } else {
             g_form.addErrorMessage('Erro ao atualizar vagas da base.')
         }
     });
 }
